#pragma once
static std::wstring ringVariantKey(int index){const auto& v=ring_library::variants[index];const auto& p=ring_library::parents[v.parent];return W(std::string(p.key)+"|"+std::to_string(index-p.firstVariant));}
void App::loadRingPreferences(){if(ringPreferencesLoaded)return;ringPreferencesLoaded=true;auto path=interfacePath();wchar_t value[512]={};GetPrivateProfileStringW(L"RingLibrary",L"Last",L"",value,512,path.c_str());for(int i=0;i<ring_library::variantCount;++i)if(ringVariantKey(i)==value)ringVariant=i;
    ringRecent.clear();for(int n=0;n<12;++n){auto key=L"Recent"+std::to_wstring(n);GetPrivateProfileStringW(L"RingLibrary",key.c_str(),L"",value,512,path.c_str());for(int i=0;i<ring_library::variantCount;++i)if(ringVariantKey(i)==value&&std::find(ringRecent.begin(),ringRecent.end(),i)==ringRecent.end())ringRecent.push_back(i);}
}
void App::rememberRing(int index){loadRingPreferences();ringVariant=index;ringRecent.erase(std::remove(ringRecent.begin(),ringRecent.end(),index),ringRecent.end());ringRecent.insert(ringRecent.begin(),index);if(ringRecent.size()>12)ringRecent.resize(12);if(testing)return;auto path=interfacePath();WritePrivateProfileStringW(L"RingLibrary",L"Last",ringVariantKey(index).c_str(),path.c_str());for(int n=0;n<12;++n){auto key=L"Recent"+std::to_wstring(n);WritePrivateProfileStringW(L"RingLibrary",key.c_str(),n<int(ringRecent.size())?ringVariantKey(ringRecent[n]).c_str():nullptr,path.c_str());}}
bool App::ringButtonAt(float x,float y){for(auto& group:visibleGroups())for(auto& button:group.items)if(button.cmd=="@otherRings"&&button.r.Contains(x,y))return true;return false;}
void App::beginRingPlacement(){if(textEditor.active&&!finishText(true))return;loadRingPreferences();s.cancel();patternPlacing=false;radicalPlacing=false;ringPlacing=true;const auto& v=ring_library::variants[ringVariant];status=std::string(ring_library::parents[v.parent].title)+" · "+v.title+"：点击画布放置，Esc 取消";SetFocus(canvas);updateCanvasCursor();invalidate();}
void App::ringMenu(){if(textEditor.active&&!finishText(true))return;loadRingPreferences();RingLibraryPicker picker;int chosen=picker.show(h,ringVariant,ringRecent);if(chosen>=0){ringVariant=chosen;beginRingPlacement();}invalidate();}
ObjectId App::insertRingTemplate(int index,Vec2 center){auto created=std::make_shared<std::vector<ObjectRef>>();auto command=ringTemplateCommand(index,center,s.doc.defaultBondLength(),created);double width=s.graphicsWidth;uint32_t color=s.graphicsColor;
    Command styled("插入环母体",kInvalidateStructure|kInvalidateGeometry|kInvalidateAppearance|kInvalidateSemantics,[command,created,width,color](CommandContext& context){auto result=command.execute(context);if(!result.ok())return result;for(auto ref:*created){auto e=graphic_style::apply(context.document,ref,width,color,width>0,true);if(!e.ok())return CommandResult::fail(e.code,e.message);}return CommandResult::success();});
    auto e=s.submit(styled,"插入环母体");if(!e.ok()){error(e);return kInvalidObjectId;}s.selected=*created;s.activateCommand("chooseSelectionTool_Marquee");rememberRing(index);status=std::string(ring_library::parents[ring_library::variants[index].parent].title)+" · 已插入，可编辑原子与化学键";invalidate();return created->empty()?kInvalidObjectId:created->front().id;
}
void App::cancelRingPlacement(){ringPlacing=false;s.ghost.clear();status="已取消环母体放置";updateCanvasCursor();invalidate();}
